    for post in posts:
        com = post.get("com", "")
        hrefs = post.get("com", "").split('href="#p')
        for href in hrefs[1:]:
            num = int(href.split('"')[0])
            if num in reply_count:
                reply_count[num] += 1
            else:
                reply_count[num] = 1
    return reply_count

def monitor_thread(board, thread_id, min_replies, delay):
    seen_posts = set()
    print(f"Monitoring thread {board}/{thread_id} every {delay} seconds…")
    tries = 0
    while True:
