                    print(f"No /aicg/ thread found in the catalog. Retrying ({tries}/5)...")
                    if tries >= 5:
                        print("No /aicg/ thread found after 5 tries. Exiting in 1 minute...")
                        time.sleep(60)
                        if not msvcrt.kbhit():
